        internal const string CleanStream = "cleanstream";
        internal const string FieldGuide = "fieldguide";
        internal const string GameTent = "gametent";
        internal const string Trailhead = "trailhead";
    }

    /// <summary>The shared library's own version, baked into every plugin that compiles it.</summary>
    internal static class CampgroundShared
    {
        /// <summary>Kept equal to the package version by CI (shared-release.yml checks the tag).</summary>
        internal const string Version = "1.0.0";
    }
